SELECT pg_temp.comment_if_exists('fact_strength_workout', 'total_reps', $c$Sum of reps across all sets.$c$);
SELECT pg_temp.comment_if_exists('fact_strength_workout', 'total_volume_kg', $c$Sum of weight_kg * reps over WORKING SETS ONLY (set_type != 'warmup').$c$);
SELECT pg_temp.comment_if_exists('fact_strength_workout', 'unique_exercises', $c$Distinct exercise_template_id count for this session.$c$);
SELECT pg_temp.comment_if_exists('fact_strength_workout', 'whoop_workout_id', $c$Soft FK to fact_workout when both apps logged the same physical session. NULL if no match within ±10/15min.$c$);
SELECT pg_temp.comment_if_exists('fact_strength_set', NULL, $c$One row per set across every Hevy session. Use this for exercise-progression / per-rep questions. Composite PK (hevy_workout_id, exercise_index, set_index) — re-ingest is a clean DELETE+INSERT per workout. Grain: 1 row per (hevy_workout_id, exercise_index, set_index)..$c$);
