SELECT pg_temp.comment_if_exists('fact_strength_set', 'day', $c$Generated from local_date(workout_start_ts). Pre-indexed.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', NULL, $c$UNIFIED per-set strength history across BOTH training eras: Hevy (fact_strength_set, through ~2026-06-04) and Whoop Strength Trainer (fact_whoop_lift_set, after). Neither source alone is a complete log. ALWAYS use this view for progression / PR / per-set questions that should span the full record — the get_whoop_lift_progression and get_whoop_lift_prs tools already read it. Warmups are excluded. Grain: 1 row per working set, across all sources.. Gotchas: exercise_id is source-local; only exercise_name is comparable across the Hevy/Whoop boundary. A lift's id differs between the two systems. is_pr is meaningful only for source='whoop'. For a true cross-era PR, rank by estimated 1RM (weight*(1+reps/30)).$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'activity_id', $c$Workout id (Whoop activity uuid as text, or Hevy workout uuid). Not globally typed — just a session grouping key.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'exercise_id', $c$Whoop exercise id OR Hevy exercise_template_id. NOT a shared namespace across sources — use exercise_norm (not exercise_id) to join a lift across eras.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'exercise_name', $c$Raw display name — differs by source (Hevy 'Deadlift (Barbell)' vs Whoop 'Deadlift - Barbell').$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'exercise_norm', $c$Canonical lift key: exercise_name lowercased with parens/hyphens normalized away, so the SAME lift unifies across the Hevy↔Whoop boundary ('deadlift barbell'). GROUP BY this for cross-era progressions/PRs — the get_whoop_lift_progression and get_whoop_lift_prs tools already do.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'set_index', $c$1-based order of the set within its exercise.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'volume_type', $c$REPS | TIME. Hevy rows are always REPS.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'reps', $c$Reps (NULL for TIME sets).$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'time_seconds', $c$Duration for TIME sets (Hevy rows carry the set's duration_seconds here, usually NULL).$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'weight_lb', $c$Weight in pounds (the user's unit). Whoop is native lbs; Hevy is converted from kg. 0 = bodyweight.$c$);
SELECT pg_temp.comment_if_exists('vw_strength_set', 'weight_kg', $c$Weight in kg (normalized both ways).$c$);
