SELECT pg_temp.comment_if_exists('fact_pushpress_session', NULL, $c$One row per programmed gym session from PushPress (the gym's workout-of-the-day across class types: CrossFit & HIIT, Barbell / Weightlifting Club, HYROX). Programmed = what the coach published, NOT what the user did — for the actually-performed view see fact_strength_workout (Hevy) and fact_workout (Whoop). Pulled by ingest_pushpress in a ±7-day window around today, daily at 4 AM ET. Always prefer the get_pushpress_* tools over raw SQL — they nest the parts[] array for free. Grain: 1 row per programmed (workout_uid).. Gotchas: Descriptions on fact_pushpress_part are FREEFORM PLAINTEXT (e.g. 'AMRAP 16: 50 Box Step-ups @ 20"'). To get structured movement counts you need an LLM-parsed version — fact_pushpress_movement is reserved but not built yet. An empty raw_pushpress_workout_of_day row with is_empty=TRUE means we asked and got nothing back (rest day or unprogrammed) — distinct from 'we never fetched this date'.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'workout_uid', $c$UUID natural key (PushPress's stable id).$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'class_type_uuid', $c$FK to dim_pushpress_class_type. The programming track.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'class_type_name', $c$Denorm of dim_pushpress_class_type.name for fast list views.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'class_date', $c$Calendar date the workout is programmed for.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'workout_state', $c$PUBLISHED | DRAFT | SCHEDULED. Filter to PUBLISHED for 'what's actually on'.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'parts_count', $c$Number of fact_pushpress_part rows for this workout.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_session', 'divisions', $c$TEXT[] — union of part-level divisions (e.g. {Performance, Fitness}).$c$);
