SELECT pg_temp.comment_if_exists('fact_pushpress_part', NULL, $c$Exploded parts of a PushPress programmed session. Each row is one section of the workout — POSTERIOR / WORKOUT OF THE DAY / A) Snatch / etc. — with the prescribed lift, score type, and the freeform plaintext description that names the movements and rep schemes. Grain: 1 row per (workout_uid, ordinal)..$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'ordinal', $c$0-indexed position within the workout (coach-authored order preserved).$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'title', $c$Section header (e.g. 'POSTERIOR', 'WORKOUT OF THE DAY').$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'workout_title', $c$Prescribed lift / WOD name (e.g. 'Deadlifts', 'Get on your hands').$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'description', $c$Freeform plaintext movements + rep schemes. The thing an LLM parser would consume.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'score_type', $c$Weight | Rounds/Reps | Time | (and others). Drives how the score field is interpreted.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'set_count', $c$Number of sets prescribed (API field 'sets').$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'default_reps', $c$Default reps per set, when applicable.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'divisions', $c$TEXT[] — Performance / Fitness / RX divisions this part applies to.$c$);
SELECT pg_temp.comment_if_exists('fact_pushpress_part', 'unit', $c$IMPERIAL | METRIC | NULL.$c$);
SELECT pg_temp.comment_if_exists('raw_hevy_routine', NULL, $c$Hevy routine templates (the user's saved programs — 'Push A', 'Pull B', etc.). Each row is one routine; payload->'exercises' is a JSONB array of {exercise_template_id, rest_seconds, sets: [{type, weight_kg, reps, rep_range, ...}]}. Workouts (raw_hevy_workout) are EXECUTIONS; routines are the PRESCRIPTIONS. Grain: 1 row per routine..$c$);
