SELECT pg_temp.comment_if_exists('fact_journal_day', 'sleep_during', $c$JSONB: the sleep window the journal applies to (if Whoop tagged one).$c$);
SELECT pg_temp.comment_if_exists('fact_whoop_metric_daily', NULL, $c$Long-format daily metrics from Whoop's PRIVATE trends API (the iOS-app data the public OAuth API doesn't expose). One row per (day, metric). This is the backbone behind several mart_daily columns and the resilience fallbacks — when the public Whoop token breaks, recovery/HRV/RHR/strain/weight still flow from here. For daily-grain questions prefer the already-pivoted mart_daily columns; query this directly only for a metric mart_daily doesn't surface. Grain: 1 row per (day, metric).. Gotchas: metric keys are UPPERCASE and exact — 'RECOVERY' not 'recovery'. (fact_biometric uses different lowercase '*_whoop' keys; don't confuse the two.) WEIGHT is stored in pounds here; mart_daily.weight_kg converts it. RECOVERY/HRV/RHR/DAY_STRAIN/SLEEP_PERFORMANCE/AVERAGE_HR were added later and currently backfill ~180 days; STEPS/CALORIES/STRESS go back further (~284 days).$c$);
SELECT pg_temp.comment_if_exists('fact_whoop_metric_daily', 'metric', $c$Whoop's trend key (UPPERCASE). Available: RECOVERY, HRV, RHR, DAY_STRAIN, SLEEP_PERFORMANCE, AVERAGE_HR, STEPS, CALORIES, RESPIRATORY_RATE, RESTORATIVE_SLEEP, SLEEP_DEBT_POST, TIME_IN_BED, HR_ZONES_1_3, HR_ZONES_4_5, STRENGTH_ACTIVITY_TIME, STRESS, STRESS_DURING_SLEEP, STRESS_DURING_NON_STRAIN, VO2_MAX, WEIGHT, BODY_COMPOSITION.$c$);
SELECT pg_temp.comment_if_exists('fact_whoop_metric_daily', 'value', $c$Numeric value (NUMERIC(14,3)). WEIGHT is in POUNDS; SLEEP_DEBT_POST is minutes.$c$);
SELECT pg_temp.comment_if_exists('fact_whoop_metric_daily', 'value_display', $c$The string Whoop's UI renders (e.g. '7:32' for a duration), pre-parse.$c$);
SELECT pg_temp.comment_if_exists('fact_whoop_metric_daily', 'unit', $c$Unit label when Whoop provides one.$c$);
SELECT pg_temp.comment_if_exists('fact_whoop_sleep_need', NULL, $c$Whoop's per-day sleep-need breakdown from the private coaching API: how much sleep you needed and why (baseline + debt + strain − nap credit). Grain: 1 row per day..$c$);
