SELECT pg_temp.comment_if_exists('raw_whoop_journal', NULL, $c$Untyped JSON payloads from Whoop's /journal-service/v3/journals/drafts/mobile/{day}. One row per day. The fact_/dim_ tables are derived from this — query raw only if you need a field that isn't pivoted. Grain: 1 row per day..$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_journal', 'day', $c$The local date the entry covers.$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_journal', 'fetched_at', $c$When the ingester last upserted this row. Useful for staleness checks.$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_journal', 'payload', $c$Full Whoop response. tracked_behaviors[], notes, integrations.tracker_inputs[], sleep_during all live here.$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', NULL, $c$Per-source credential store. Single row per `service`. `whoop_private` is the Whoop iOS-API token — now refreshed SERVER-SIDE via AWS Cognito (lifeos_core.whoop_cognito), consumed by both ingest_whoop_journal and ingest_whoop_private. Other services: `whoop` (public OAuth), `google`, `copilot`. Grain: 1 row per service.. Gotchas: Don't update partial — always pass all five token columns when writing, or you'll silently null id_token / metadata. whoop_private refresh is now fully server-side (Cognito): a stale access_token self-heals on the next ingest. Only a dead/expired REFRESH token (~30 days idle) requires re-running `python -m ingest_whoop_private login`. The iPhone Shortcut bridge is retired.$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', 'service', $c$Source key. Lookup with WHERE service = '<name>'.$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', 'access_token', $c$Bearer token. Short-lived (~24h for Whoop).$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', 'refresh_token', $c$Long-lived. For whoop_private it's the Cognito refresh token (~30 days); the server auto-rotates the access token from it.$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', 'id_token', $c$Optional. Cognito JWT with identity claims (sub, email). Populated for whoop_private; null for OAuth-only sources.$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', 'expires_at', $c$When access_token expires. The Whoop auth layer auto-refreshes via Cognito when within a 5-min skew of this; raises WhoopAuthExpired only if the refresh token itself is dead.$c$);
SELECT pg_temp.comment_if_exists('oauth_tokens', 'metadata', $c$JSONB. Provenance hints like {"source": "cognito_refresh", "received_at": "..."}.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', NULL, $c$Catalog of every biomarker Whoop Advanced Labs measures (75 in the Comprehensive Health Panel). Curated reference data: description, category, optimal/sufficient ranges, what high/low means, and influencing factors. Joined to fact_lab_result on biomarker_id. CONSULT THIS FOR ANY HEALTH QUESTION involving blood markers, hormones, lipids, kidney/liver function, inflammation, or vitamins. Grain: 1 row per biomarker.. Gotchas: Rows with category='external' are auto-stubbed by submit_lab_results for biomarkers Whoop's catalog doesn't cover. They carry the submitted ranges but lack the rich what_high/low_means narrative — that's expected.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'biomarker_id', $c$Whoop's stable slug — e.g. 'apolipoprotein_b', 'vitamin_d', 'hemoglobin_a1c'.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'category', $c$Cardiometabolic | Liver | Kidney | Hormones | Inflammation | Blood Count | Iron Metabolism | Vitamins & Minerals.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'optimal_low', $c$Tight clinical target (Whoop's 'Optimal' band). Inside this = OPTIMAL classification.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'optimal_high', $c$Tight clinical target (Whoop's 'Optimal' band). Inside this = OPTIMAL classification.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'sufficient_low', $c$Outer acceptable range. Outside this = OUT_OF_RANGE.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'sufficient_high', $c$Outer acceptable range. Outside this = OUT_OF_RANGE.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'what_high_means', $c$Clinical interpretation strings — surface these when explaining a result.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'what_low_means', $c$Clinical interpretation strings — surface these when explaining a result.$c$);
SELECT pg_temp.comment_if_exists('dim_lab_biomarker', 'influenced_by', $c$Lifestyle / drug / physiologic factors that shift the value.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', NULL, $c$Per-biomarker lab results. One row per (test_id, biomarker_id). Holds BOTH Whoop Advanced Labs panels (source='whoop') and externally-submitted labs the user hands over directly (source='external', written by the submit_lab_results tool). Always join to dim_lab_biomarker for descriptions/ranges — the get_lab_results tool composes that join for you and spans both sources transparently. Grain: 1 row per (test_id, biomarker_id).. Gotchas: range_meter (Whoop) holds 0-1 normalized positions, NOT absolute bounds. For absolute ranges read reference_ranges (external) or dim_lab_biomarker.optimal_low/high & sufficient_low/high (Whoop). Same biomarker can appear in multiple panels/draws over time — filter by test_id or test_date for a specific draw. To submit an external lab, use the submit_lab_results tool (it writes raw_external_lab + dim_lab_biomarker stubs + these rows); don't INSERT by hand.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'value_text', $c$Raw value as displayed (e.g. '6.0', '293.0', '0.31').$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'value_numeric', $c$Parsed numeric for filtering/comparison.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'status_type', $c$OPTIMAL | SUFFICIENT | OUT_OF_RANGE. For external labs without an explicit status it's derived from the supplied ranges.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'source', $c$'whoop' (Advanced Labs) | 'external' (user-submitted, e.g. a clinic blood draw). Default 'whoop'.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'lab_provider', $c$Free-text lab/clinic name for external results (e.g. 'Quest', 'LabCorp'). NULL for Whoop.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'reference_ranges', $c$JSONB {optimal:{lower_endpoint,upper_endpoint}, sufficient:{...}} captured at submit time for external labs. (Whoop rows keep ranges on dim_lab_biomarker.)$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'trend', $c$POSITIVE_RANGE | SUFFICIENT_BLUE | CONCERN_RANGE — Whoop UI tint hint. NULL for external.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'indicator_percent', $c$Where the value sits on Whoop's range meter, 0-1. NULL for external.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_result', 'range_meter', $c$JSONB of normalized meter sections + indicator. Whoop UI geometry, not absolute units.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', NULL, $c$Radiology / imaging studies the user submits directly (MRI, X-ray, CT, ultrasound, DEXA, ...). Written by the submit_imaging_study tool and read by get_imaging_studies. Consult for any musculoskeletal / structural health question (back pain, joint issues, the user's HLA-B27 / SI-joint workup, etc.). Grain: 1 row per (modality, body_region, study_date) study_id..$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'modality', $c$MRI | X-RAY | CT | ULTRASOUND | DEXA | ...$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'body_region', $c$e.g. 'lumbar spine', 'SI joints'.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'impression', $c$The radiologist's summary/impression — usually the most useful field.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'findings', $c$JSONB array of {location, finding, severity?}.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'raw_text', $c$Full report text, verbatim, when the user provided it.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'ordering_reason', $c$Why the study was ordered, if given.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging_study', 'source', $c$'external' (all imaging is user-submitted today).$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_labs', NULL, $c$Raw JSON payloads from Whoop Advanced Labs panels. Keyed by test_id. Grain: 1 row per panel test..$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_labs', 'test_id', $c$Whoop's UUID for the test.$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_labs', 'test_name', $c$e.g. 'Comprehensive Health Panel (75)'.$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_labs', 'test_date', $c$Date of blood draw (parsed from the panel header).$c$);
SELECT pg_temp.comment_if_exists('raw_whoop_labs', 'payload', $c$Full UI JSON dump — only useful as a fallback; everything actionable is parsed into fact_lab_result.$c$);
SELECT pg_temp.comment_if_exists('fact_food_daily_apple_health', NULL, $c$Daily macros from Apple Health, pulled via Whoop's integrations.tracker_inputs. Use for cross-validation with Cronometer's fact_food_daily, or as a fallback when Cronometer is broken. Grain: 1 row per day..$c$);
SELECT pg_temp.comment_if_exists('fact_food_log', NULL, $c$Every individual food item logged in Cronometer with timestamp. Grain: 1 row per logged serving.. Gotchas: Two paths feed this table: (1) the nightly Go-binary GWT pipeline (servings + daily-nutrition CSV → fact_food_log / fact_food_daily) and (2) the MCP write tools (log_food / delete_food_entry) which hit mobile.cronometer.com to write to Cronometer's diary, then immediately auto-trigger path (1) so the new row lands here within seconds. mart_daily rollups are NOT auto-refreshed — call refresh_data('mart') if you need today's totals reflected. Batch flows can pass sync=False on each write and sync once at the end.$c$);
SELECT pg_temp.comment_if_exists('fact_food_log', 'eaten_at', $c$UTC timestamp. Cronometer per-meal time (Gold required).$c$);
SELECT pg_temp.comment_if_exists('fact_food_log', 'meal_group', $c$Cronometer label: Breakfast | Lunch | Dinner | Snack 1/2/3 | Uncategorized.$c$);
SELECT pg_temp.comment_if_exists('fact_food_log', 'micros', $c$JSONB of every micronutrient Cronometer reported (vitamins, minerals, amino acids).$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', NULL, $c$Every Copilot Money transaction. Grain: 1 row per transaction..$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'amount', $c$Positive = expense, negative = income or refund (Copilot convention).$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'is_excluded', $c$True if 'exclude from totals' is set in Copilot.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'category_id', $c$FK to dim_category.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'tags', $c$TEXT[] of human-readable tag names (e.g. ['Santi', 'Trip Tahiti']). Use the `tag` filter on get_transactions to query by name.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'tag_ids', $c$TEXT[] of Copilot tag UUIDs aligned with `tags`. Used internally by set_couple_tag.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'is_reviewed', $c$True if you've marked the transaction reviewed in Copilot.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'tip_amount', $c$Tip portion of the transaction, if any.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'parent_id', $c$If this is a split transaction, the parent's ID.$c$);
SELECT pg_temp.comment_if_exists('fact_transaction', 'copilot_type', $c$Copilot's internal type field (regular | transfer | etc.).$c$);
SELECT pg_temp.comment_if_exists('dim_possession', NULL, $c$Every physical possession — clothing, footwear, bags, tech, toiletries and gear in ONE table. A charger and a t-shirt both need 'where is it' and 'did I take it'. Prefer the view mart_possession_summary, which adds wear counts and cost per wear. Grain: 1 row per owned item..$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'kind', $c$possession_kind enum: top | bottom | outerwear | footwear | headwear | accessory | bag | tech | toiletry | gear | other.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'subcategory', $c$Controlled per kind via a composite FK to dim_possession_subcategory, so 'running shoe' can only attach to footwear.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'primary_color / secondary_color', $c$FK to dim_color. A value outside the vocabulary is REJECTED, not coerced — call get_possession_vocab before writing.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'colorway', $c$Free text: the manufacturer's colour name as sold ('Alloy/Ivory'). Not a second guess at primary_color.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'formality', $c$1 gym/lounge, 2 casual, 3 smart casual, 4 business, 5 formal. Items where it doesn't apply are 2.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'warmth', $c$1 hot-weather only, 3 three-season, 5 deep winter. Items with no thermal role are 1.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'weather_tags', $c$text[] of rain | wind | cold | heat | humid — what the item is BUILT for, not what it tolerates.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'status', $c$possession_status enum: active | purge_candidate | listed | donated | sold | retired. Nothing is deleted; a donated item keeps its wear history so cost-per-wear stays honest.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'cost_cents', $c$Nullable and left NULL when unknown. A fabricated price poisons cost_per_wear for every item that has a real one.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'photo_original / photo_cutout / photo_thumb', $c$Supabase Storage paths, never blobs. Originals are kept forever so segmentation can be re-run with a better model.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'photo_hash', $c$sha256 of the original bytes. UNIQUE — this is what makes re-running the batch ingest a no-op instead of a second closet.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'tag_confidence', $c$jsonb {field: 0..1} from the vision tagger. Drives which fields the review queue asks a human to check.$c$);
SELECT pg_temp.comment_if_exists('dim_possession', 'reviewed', $c$FALSE until a human confirmed the auto-tags. Treat brand/colour/material on unreviewed rows as provisional and SAY SO.$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', NULL, $c$Per-possession wear economics. A view over dim_possession + fact_wear. Read this rather than joining fact_wear by hand. Grain: 1 row per possession..$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', 'wear_count_30 / _90 / _365 / _all', $c$Wear counts over trailing windows.$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', 'last_worn_on', $c$NULL when never worn — which is the strongest purge signal there is, not missing data.$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', 'days_since_worn', $c$NULL when never worn — which is the strongest purge signal there is, not missing data.$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', 'cost_per_wear_cents', $c$cost_cents / wear_count_all. NULL when either is unknown.$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', 'is_stale', $c$active, acquired >180d ago, and unworn for >180d.$c$);
SELECT pg_temp.comment_if_exists('mart_possession_summary', 'location_path', $c$Full nested container path, e.g. 'Bedroom / Under bed / Bin A'.$c$);
SELECT pg_temp.comment_if_exists('fact_wear', NULL, $c$One row per (possession, day, context) that an item was used. Grain: 1 row per item per day per context..$c$);
SELECT pg_temp.comment_if_exists('fact_wear', 'context', $c$work | gym | travel | social | home.$c$);
SELECT pg_temp.comment_if_exists('fact_wear', 'worn_on', $c$Local date.$c$);
SELECT pg_temp.comment_if_exists('fact_wear', '_unique', $c$UNIQUE (possession_id, worn_on, context) — log_wear is safe to call twice.$c$);
SELECT pg_temp.comment_if_exists('dim_storage_location', NULL, $c$Containers, nested via parent_id: Bedroom -> Under bed -> Bin A. Query vw_storage_location for the resolved full_path and active item count. Grain: 1 row per container..$c$);
SELECT pg_temp.comment_if_exists('dim_storage_location', 'kind', $c$closet | bin | drawer | bag | rack | shelf | offsite.$c$);
SELECT pg_temp.comment_if_exists('dim_storage_location', 'parent_id', $c$Self-reference. get_storage_contents is nested by default, so asking about a parent finds what's in its children.$c$);
SELECT pg_temp.comment_if_exists('dim_trip', NULL, $c$A trip and its destination legs; drives build_packing_list. Grain: 1 row per trip..$c$);
SELECT pg_temp.comment_if_exists('dim_trip', 'destinations', $c$jsonb array of {city, from, to, weather_tags[], low_c, high_c, formality:[min,max], international}. build_packing_list UNIONS these into one requirement set — a warm rainy city plus a cold one needs both a shell and a warm layer, not the average.$c$);
SELECT pg_temp.comment_if_exists('bridge_trip_packing', NULL, $c$What was shortlisted, packed, actually worn, or carried unused on a trip. Grain: 1 row per (trip, possession)..$c$);
SELECT pg_temp.comment_if_exists('bridge_trip_packing', 'state', $c$candidate | packed | worn | unused. Recording worn/unused after the trip is what makes the next list better.$c$);
SELECT pg_temp.comment_if_exists('bridge_trip_packing', 'slot', $c$Which packing requirement selected the item.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', NULL, $c$Forensic log of every DB write Claude makes via the generic db_* / execute_sql tools and via the possession write tools — including dry-runs, blocked attempts, and failures. The older semantic write tools (log_food etc.) are not logged here. Use get_write_audit to review or reconstruct changes. Grain: 1 row per write-tool call..$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'tool', $c$execute_sql | db_insert | db_update | db_delete | db_upsert.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'operation', $c$INSERT | UPDATE | DELETE | UPSERT | DDL_* | TRUNCATE | …$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'target_table', $c$Best-effort table the statement touched.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'statement', $c$The exact SQL sent (with %s placeholders).$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'params', $c$JSONB summary of the bound params (truncated).$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'affected_rows', $c$cur.rowcount after execution.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'dry_run', $c$True if previewed-and-rolled-back.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'committed', $c$True only if the change was actually applied.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'ok', $c$False if the statement errored or was refused by a guard.$c$);
SELECT pg_temp.comment_if_exists('mcp_write_audit', 'result_sample', $c$Sample of RETURNING rows, if any.$c$);
SELECT pg_temp.comment_if_exists('fact_activity', NULL, $c$One row per training session, any source. Cluster-deduped: rows describing the same real session share cluster_id and exactly one has is_primary. The primary is enriched with every non-NULL field its siblings have, so it is strictly richer than any single source. Read vw_activity, not this.$c$);
SELECT pg_temp.comment_if_exists('fact_activity_exercise', NULL, $c$Per-exercise rollup. granularity='set' means derived from real per-set rows (Whoop/Hevy); granularity='exercise' means the vendor only exported aggregates (Garmin, Dec 2024 – Aug 2025).$c$);
SELECT pg_temp.comment_if_exists('fact_activity_set', NULL, $c$True per-set rows: reps, weight_kg, rpe, per-set HR. Only Whoop Strength Trainer and Hevy populate this.$c$);
SELECT pg_temp.comment_if_exists('fact_sleep_session', NULL, $c$One row per sleep or nap, any source. Main sleeps cluster by wake day; naps cluster by overlap.$c$);
SELECT pg_temp.comment_if_exists('fact_nutrition_entry', NULL, $c$Per food item across Cronometer, Lose It, Cal AI.$c$);
SELECT pg_temp.comment_if_exists('fact_nutrition_daily', NULL, $c$Daily totals per source. vw_nutrition_daily picks one source per day by precedence.$c$);
SELECT pg_temp.comment_if_exists('fact_body_composition', NULL, $c$Weight/body fat with the METHOD that produced it (dxa|bodpod|bioimpedance|calipers|tape|scale|manual). A DXA and a wrist bioimpedance reading are not interchangeable and are never averaged.$c$);
SELECT pg_temp.comment_if_exists('fact_daily_metric', NULL, $c$Long-format daily metrics (steps, resting_hr, hrv, vo2_max, calories, stress, spo2) per source. vw_daily_metric picks the best source per (day, metric).$c$);
SELECT pg_temp.comment_if_exists('fact_fast', NULL, $c$Fasting windows from Zero.$c$);
SELECT pg_temp.comment_if_exists('fact_lab_panel / fact_lab_measurement', NULL, $c$One row per blood draw, one per analyte, on canonical biomarker_key. The same draw reported by two systems is collapsed.$c$);
SELECT pg_temp.comment_if_exists('fact_imaging', NULL, $c$MRI/CT/X-ray/ultrasound/DEXA with impression and structured findings.$c$);
SELECT pg_temp.comment_if_exists('raw_import', NULL, $c$Immutable JSONB landing for every file import, keyed (source, entity, natural_key). Never transformed. Every canonical table is a pure function of this plus the source fact tables, so `python -m unify all --rebuild` is always safe.$c$);
SELECT pg_temp.comment_if_exists('source_health', NULL, $c$Per-stream registry: mode, SLA, coverage window, last row. Drives vw_data_freshness.$c$);
SELECT pg_temp.comment_if_exists('data_quality_flag', NULL, $c$Implausible readings. Flagged, never deleted — a 239.4 lb reading among eight 176-179 lb readings says something about the scale, and deleting it destroys that evidence. Read paths exclude flagged rows by default.$c$);
SELECT pg_temp.comment_if_exists('vw_activity', NULL, $c$One row per real session. Use this, not fact_workout.$c$);
SELECT pg_temp.comment_if_exists('vw_activity_exercise / vw_activity_set', NULL, $c$Cross-source exercise and set detail with canonical movement names, muscle group, and is_spinal_flexion.$c$);
SELECT pg_temp.comment_if_exists('vw_sleep_daily', NULL, $c$One main sleep per day, best source, with naps summarized.$c$);
SELECT pg_temp.comment_if_exists('vw_nutrition_daily', NULL, $c$One row per day, best source, with source_count so you can see when sources disagree.$c$);
SELECT pg_temp.comment_if_exists('vw_body_daily', NULL, $c$One weight + body-fat reading per day. DXA outranks BodPod outranks scale outranks bioimpedance.$c$);
SELECT pg_temp.comment_if_exists('vw_daily_metric', NULL, $c$One value per (day, metric), best source.$c$);
SELECT pg_temp.comment_if_exists('vw_adherence', NULL, $c$Rolling 4/12/26-week sessions per week plus below_floor.$c$);
SELECT pg_temp.comment_if_exists('vw_data_freshness', NULL, $c$Per-source status: ok | lagging | stale | historical | retired | no_data.$c$);
SELECT pg_temp.comment_if_exists('vw_coverage_daily', NULL, $c$Day-by-day booleans for has_activity / has_sleep / has_nutrition / has_weight, with the contributing sources.$c$);
